def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, take what we can afford but avoid overspending.
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday trace bids (immediate reaction only)
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Estimate supply pressure: if supply is tight (< WATER_REQ), any water is scarce.
    tight_supply = supply < float(WATER_REQ)

    # Determine opponent urgency from their previous bids.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base bid depending on our HP.
    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    # Aggressive threshold: if opponents were already bidding high, we must match.
    urgent = highest_prev_bid >= DAILY_SALARY * 0.85

    # Compute candidate bids.
    if urgent:
        # If we are healthy, spend enough to likely win; if low HP, spend more.
        if hp > 3:
            bid = DAILY_SALARY * 0.3
        else:
            bid = DAILY_SALARY * 0.95

        # If supply is very tight, raise slightly to secure allocation.
        if tight_supply:
            bid = bid * 1.15

        # Also ensure we are not bidding far below their last highest.
        bid = max(bid, highest_prev_bid * 0.95)
    else:
        # Not urgent: bid moderately, but slightly higher if tight supply.
        if hp <= 2:
            bid = DAILY_SALARY * 0.75
        else:
            bid = DAILY_SALARY * (0.55 if not tight_supply else 0.7)

        # If we saw some bidding activity, bid just above that activity to steal water.
        if yesterday_bids:
            bid = max(bid, highest_prev_bid + 1.5)

    # Clamp to budget and non-negative.
    if budget <= 0:
        return 0

    bid = min(float(budget), float(bid))
    if bid < 0:
        bid = 0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_opp += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return max(0, min(budget, 1.0))

    units = supply / WATER_REQ
    scarcity = 0
    if units < 2:
        scarcity = 2
    elif units < 3:
        scarcity = 1

    if hp <= 2 or no_water_days >= 2:
        emergency = min(budget, DAILY_SALARY * 0.98)
        if prev_bids:
            emergency = min(budget, max(emergency, max(prev_bids) + 2.0))
        return max(0, emergency)

    target = DAILY_SALARY * 0.42

    if scarcity == 2:
        target = DAILY_SALARY * 0.72
    elif scarcity == 1:
        target = DAILY_SALARY * 0.58
    else:
        target = DAILY_SALARY * 0.36

    if hp <= 4:
        target += DAILY_SALARY * 0.12
    if no_water_days == 1:
        target += DAILY_SALARY * 0.10

    if desperate_opp > 0:
        target += 6.0 * desperate_opp
    if rich_opp > 0 and scarcity > 0:
        target += 3.0

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if scarcity == 2:
            target = max(target, highest_prev + 2.0)
        elif scarcity == 1:
            target = max(target, avg_prev + 1.5)
        else:
            target = min(target, max(DAILY_SALARY * 0.28, avg_prev * 0.9))

    if day >= 8:
        target += 4.0

    target = min(target, DAILY_SALARY * 0.98)
    target = min(target, budget)
    if budget < DAILY_SALARY * 0.35 and hp > 3 and no_water_days == 0:
        target = min(target, budget * 0.55)

    return max(0, float(target))
